WITH combined AS ( SELECT 'REFUNDED' AS role, cr.cr_refunded_hdemo_sk AS hd_demo_sk, cr.cr_return_quantity, cr.cr_net_loss FROM catalog_returns cr UNION ALL SELECT 'RETURNING' AS role, cr.cr_returning_hdemo_sk, cr.cr_return_quantity, cr.cr_net_loss FROM catalog_returns cr ) SELECT role, hd.hd_demo_sk, hd.hd_income_band_sk, hd.hd_vehicle_count, SUM(combined.cr_return_quantity) AS total_return_qty, AVG(combined.cr_net_loss) AS avg_net_loss, COUNT(*) AS return_records, CASE WHEN SUM(combined.cr_net_loss) > 15000 THEN 'HIGH' WHEN SUM(combined.cr_net_loss) > 5000 THEN 'MEDIUM' ELSE 'LOW' END AS loss_category FROM combined JOIN household_demographics hd ON combined.hd_demo_sk = hd.hd_demo_sk WHERE hd.hd_dep_count >= 2 GROUP BY role, hd.hd_demo_sk, hd.hd_income_band_sk, hd.hd_vehicle_count ORDER BY avg_net_loss DESC
